SELECT id, city, opened_date, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date ASC, id ASC) AS row_seq, MAX(sqft) OVER (PARTITION BY city) AS city_max_sqft, ROUND(sqft / SUM(sqft) OVER (PARTITION BY city, region), 4) AS sqft_share, SUM(sqft) OVER (ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft, NTILE(4) OVER (PARTITION BY region ORDER BY sqft DESC, id ASC) AS sqft_bucket FROM stores;
